// The silhouette the block samples, inlined as a data URI.
//
// A shadcn registry item carries text files only, so a .jpg beside the
// component would not survive `npx shadcn add` — the image has to travel as
// source. Downscaled to 600px square (the canvas draws it at ~295px, so this is
// still 2x) to keep the registry JSON sane.
export const OWL_SRC =
  "data:image/jpeg;base64,";
